fn all_characters_same(s: &[u8]) -> bool {
    // An empty slice or a single-element slice is trivially all the same.
    if s.len() <= 1 {
        return true;
    }

    // Otherwise, compare every element to the first one.
    let first = s[0];
    for &c in &s[1..] {
        if c != first {
            return false;
        }
    }
    true
}

